#!/usr/bin/env python3
"""Embed the canonical Python helper in a single downloadable Bash launcher."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
header = r'''#!/usr/bin/env bash
# Shello pairing launcher. Generated by scripts/generate-pair-script.py.
# Run as your SSH user; requires Python >=3.9, OpenSSL, tmux and enabled SSH.
set -euo pipefail
umask 077
command -v python3 >/dev/null || { echo 'Install Python 3.9+ first.' >&2; exit 1; }
python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3,9) else "Python 3.9+ is required")'
work=$(mktemp -d "${TMPDIR:-/tmp}/shello-pair.XXXXXX")
trap 'rm -rf "$work"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
cat > "$work/pair.py" <<'SHELLO_PAIR_PYTHON'
'''
footer = r'''SHELLO_PAIR_PYTHON
if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
    python3 "$work/pair.py" --help
    exit 0
fi
for dependency in openssl tmux; do
    command -v "$dependency" >/dev/null || { echo "Install $dependency first, then run this command again." >&2; exit 1; }
done
pair_home="${SHELLO_PAIR_HOME:-$HOME/.local/share/shello/pair}"
mkdir -p "$pair_home"
chmod 700 "$pair_home"
if [[ ! -x "$pair_home/venv/bin/python" ]]; then
    python3 -m venv "$pair_home/venv" || { echo 'Cannot create a virtual environment. On Debian/Ubuntu install python3-venv.' >&2; exit 1; }
fi
if ! "$pair_home/venv/bin/python" -c 'from importlib.metadata import version; assert version("qrcode") == "8.2"' 2>/dev/null; then
    "$pair_home/venv/bin/python" -m pip --disable-pip-version-check install 'qrcode==8.2'
fi
# Do not exec: the EXIT trap removes the temporary helper even after interruption.
"$pair_home/venv/bin/python" "$work/pair.py" "$@"
'''
script = root / 'companion/pair.sh'
script.write_text(header + (root / 'companion/pair.py').read_text() + '\n' + footer)
script.chmod(0o755)
